NUL = 1000

def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == NUL:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != NUL]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def maxPathSumAtMostK(tree, k):
    vals, left, right = _links(tree)
    n = len(vals)
    zero = [0] * (k + 1)
    rows = [None] * n
    best = -10 ** 9
    for v in range(n - 1, -1, -1):
        A = rows[left[v]] if left[v] != -1 else zero
        B = rows[right[v]] if right[v] != -1 else zero
        m = -10 ** 9
        for a in range(k):
            t = A[a] + B[k - 1 - a]
            if t > m:
                m = t
        if vals[v] + m > best:
            best = vals[v] + m
        row = [0] * (k + 1)
        x = vals[v]
        for j in range(1, k + 1):
            t = x + (A[j - 1] if A[j - 1] > B[j - 1] else B[j - 1])
            row[j] = t if t > 0 else 0
        rows[v] = row
        if left[v] != -1:
            rows[left[v]] = None
        if right[v] != -1:
            rows[right[v]] = None
    return best
